-- 홈 스토어 — 로컬 개발용 시드
--
-- ⚠ 이 시드는 화면 개발용 표본일 뿐이다.
--   M4 의 AC2(등록 median ≤10초) 판정에는 **절대 쓰지 않는다.**
--   그 판정은 실기기에서 손으로 넣은 20개로만 한다 (계획 §3 시나리오 2).
--   "개발자가 손으로 넣기 싫어 시드를 만들기 시작함" 이 바로 그 실패의 조기 경보다.

insert into auth.users (id, instance_id, aud, role, email, encrypted_password,
                        email_confirmed_at, created_at, updated_at, raw_user_meta_data)
values
  ('00000000-1111-1111-1111-000000000001','00000000-0000-0000-0000-000000000000',
   'authenticated','authenticated','dev1@homestore.test',
   crypt('devpassword', gen_salt('bf')), now(), now(), now(), '{"full_name":"김보관"}'),
  ('00000000-1111-1111-1111-000000000002','00000000-0000-0000-0000-000000000000',
   'authenticated','authenticated','dev2@homestore.test',
   crypt('devpassword', gen_salt('bf')), now(), now(), now(), '{"full_name":"이정리"}')
on conflict (id) do nothing;

